CREATE TABLE cerrojo_dominio (id INT PRIMARY KEY) ENGINE=InnoDB;
INSERT INTO cerrojo_dominio VALUES (1);
CREATE TABLE usuarios (id VARCHAR(100) PRIMARY KEY,nombre VARCHAR(120) NOT NULL,correo VARCHAR(254) NOT NULL UNIQUE,telefono VARCHAR(30) NOT NULL,rol ENUM('administrador','cliente') NOT NULL) ENGINE=InnoDB;
CREATE TABLE articulos (id VARCHAR(100) PRIMARY KEY,nombre VARCHAR(120) NOT NULL,descripcion VARCHAR(1000) NOT NULL,categoria VARCHAR(80) NOT NULL,precioDiaCentavos BIGINT NOT NULL,cargoDanoCentavos BIGINT NOT NULL,valorReposicionCentavos BIGINT NOT NULL,totalPiezas BIGINT NOT NULL,activo BOOLEAN NOT NULL,CHECK(totalPiezas>=0),CHECK(precioDiaCentavos>0),CHECK(cargoDanoCentavos>=0 AND cargoDanoCentavos<=valorReposicionCentavos)) ENGINE=InnoDB;
CREATE TABLE fotografias (articuloId VARCHAR(100) NOT NULL,posicion INT NOT NULL,referencia VARCHAR(1000) NOT NULL,PRIMARY KEY(articuloId,posicion),FOREIGN KEY(articuloId) REFERENCES articulos(id)) ENGINE=InnoDB;
CREATE TABLE reservas (
id VARCHAR(100) PRIMARY KEY,clienteId VARCHAR(100) NOT NULL,desde VARCHAR(10) NOT NULL,hasta VARCHAR(10) NOT NULL,dias INT NOT NULL,
rentaCentavos BIGINT NOT NULL,depositoCentavos BIGINT NOT NULL,totalInicialCentavos BIGINT NOT NULL,direccionEntrega VARCHAR(500) NOT NULL,
estado ENUM('apartada','entregada','devuelta','cancelada') NOT NULL,creadaEn VARCHAR(35) NOT NULL,
entregaReal VARCHAR(35),entregaFecha VARCHAR(10),recoleccionReal VARCHAR(35),recoleccionFecha VARCHAR(10),canceladaEn VARCHAR(35),motivoCancelacion VARCHAR(500),
solicitadaEn VARCHAR(35),motivoSolicitud VARCHAR(500),politicaSolicitud VARCHAR(1000),
rentaCobradaCentavos BIGINT NOT NULL,depositoCobradoCentavos BIGINT NOT NULL,depositoDevueltoCentavos BIGINT NOT NULL,depositoDevueltoEn VARCHAR(35),cargoIncidenciasCentavos BIGINT NOT NULL,saldoIncidenciasCentavos BIGINT NOT NULL,
FOREIGN KEY(clienteId) REFERENCES usuarios(id),CHECK(hasta>=desde),CHECK(dias>0)) ENGINE=InnoDB;
CREATE TABLE detalles_reserva (reservaId VARCHAR(100) NOT NULL,posicion INT NOT NULL,articuloId VARCHAR(100) NOT NULL,nombre VARCHAR(120) NOT NULL,cantidad BIGINT NOT NULL,precioDiaCentavos BIGINT NOT NULL,cargoDanoCentavos BIGINT NOT NULL,valorReposicionCentavos BIGINT NOT NULL,subtotalCentavos BIGINT NOT NULL,PRIMARY KEY(reservaId,posicion),UNIQUE(reservaId,articuloId),FOREIGN KEY(reservaId) REFERENCES reservas(id),FOREIGN KEY(articuloId) REFERENCES articulos(id),CHECK(cantidad>0)) ENGINE=InnoDB;
CREATE TABLE recolecciones (reservaId VARCHAR(100) NOT NULL,posicion INT NOT NULL,articuloId VARCHAR(100) NOT NULL,buenas BIGINT NOT NULL,danadas BIGINT NOT NULL,faltantes BIGINT NOT NULL,PRIMARY KEY(reservaId,posicion),UNIQUE(reservaId,articuloId),FOREIGN KEY(reservaId) REFERENCES reservas(id),FOREIGN KEY(articuloId) REFERENCES articulos(id),CHECK(buenas>=0 AND danadas>=0 AND faltantes>=0)) ENGINE=InnoDB;
CREATE TABLE bloqueos (id VARCHAR(100) PRIMARY KEY,articuloId VARCHAR(100) NOT NULL,cantidad BIGINT NOT NULL,desde VARCHAR(10) NOT NULL,hasta VARCHAR(10) NOT NULL,tipo ENUM('mantenimiento','dano','faltante') NOT NULL,motivo VARCHAR(500) NOT NULL,reservaId VARCHAR(100),FOREIGN KEY(articuloId) REFERENCES articulos(id),FOREIGN KEY(reservaId) REFERENCES reservas(id),CHECK(cantidad>0),CHECK(hasta>=desde)) ENGINE=InnoDB;
CREATE TABLE ajustes (id VARCHAR(100) PRIMARY KEY,articuloId VARCHAR(100) NOT NULL,anterior BIGINT NOT NULL,nueva BIGINT NOT NULL,motivo VARCHAR(500) NOT NULL,registradoEn VARCHAR(35) NOT NULL,FOREIGN KEY(articuloId) REFERENCES articulos(id),CHECK(anterior>=0 AND nueva>=0)) ENGINE=InnoDB;
